"""Create inert, browser-readable copies of TEMP PHP files; never execute PHP.
Requires Pygments (pip install pygments). Run from any directory.
"""
from pathlib import Path
import html
import os
from urllib.parse import quote
from pygments import lex
from pygments.lexers import PhpLexer
from pygments.token import Other

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / 'TEMP'
OUTPUT = SOURCE / 'HTML-PREVIEW'
STYLE = '''body{font:16px/1.55 system-ui,sans-serif;max-width:1200px;margin:32px auto;padding:0 24px;color:#202938;background:#f7f9fc}a{color:#1752a0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:white;padding:20px;border:1px solid #ccd3df}iframe{width:100%;height:500px;border:1px solid #ccd3df;background:white}input{font:inherit;padding:10px;width:90%}li{margin:8px 0}.note{padding:16px;background:#fff2cd}summary{cursor:pointer;font-weight:bold}'''
def page(title, body):
    return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+STYLE+'</style><body>'+body+'</body></html>'
def generate():
    files = sorted((p for p in SOURCE.rglob('*') if p.suffix.lower()=='.php' and OUTPUT not in p.parents),key=lambda p:('themes/aiobservatory/' not in p.as_posix(),p.as_posix()))
    rows=[]
    for source in files:
        rel=source.relative_to(SOURCE)
        target=OUTPUT/'files'/rel.with_suffix('.html')
        target.parent.mkdir(parents=True,exist_ok=True)
        text=source.read_text(encoding='utf-8',errors='replace')
        # A lexer respects strings/comments containing ?>; regex stripping does not.
        markup=''.join(value if token in Other else '' for token,value in lex(text,PhpLexer(startinline=False)))
        has_markup=bool(markup.strip())
        home=quote(os.path.relpath(OUTPUT/'index.html',target.parent).replace(os.sep,'/'))
        body='<a href="'+home+'">← All PHP files</a><h1>'+html.escape(str(rel))+'</h1>'
        body+='<p class="note">Archive inspection copy. PHP has not been run. WordPress database content, includes, forms and dynamic output are not reconstructed. The source below is complete; the preview shows only literal HTML outside PHP blocks.</p>'
        if has_markup:
            # Sandboxed frame: no scripts, forms, navigation of parent or network assets.
            preview='<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; form-action \'none\'; base-uri \'none\'"><style>body{font:16px system-ui;overflow-wrap:anywhere}img{max-width:100%}</style>'+markup
            body+='<h2>Static HTML fragment preview</h2><p>Layout and images may be incomplete because dependencies and PHP output are omitted.</p><iframe sandbox="" referrerpolicy="no-referrer" title="Static fragment preview" srcdoc="'+html.escape(preview,quote=True)+'"></iframe>'
        else:
            body+='<p><strong>PHP code only:</strong> this file contains no standalone HTML to preview.</p>'
        body+='<details'+('' if has_markup else ' open')+'><summary>Complete original source</summary><pre>'+html.escape(text)+'</pre></details>'
        target.write_text(page(str(rel),body),encoding='utf-8')
        href=quote(target.relative_to(OUTPUT).as_posix())
        rows.append('<li><a href="'+href+'">'+html.escape(rel.as_posix())+'</a> — '+('HTML fragment' if has_markup else 'PHP code only')+'</li>')
    body='<h1>Original PHP archive</h1><p>'+str(len(files))+' browser-readable files. Site theme files appear first, followed by other themes and plugins.</p><p class="note">These are inspection copies, not functioning conversions of the old WordPress site. Open any file to inspect its source and available static HTML. No PHP server is needed.</p><label>Filter by filename or folder<br><input id="filter" type="search" placeholder="Try aiobservatory, reserve, header…"></label><p id="count"></p><ul>'+''.join(rows)+'</ul>'
    body+='''<script>const rows=[...document.querySelectorAll('li')];document.querySelector('#filter').addEventListener('input',function(){let n=0;for(const row of rows){row.hidden=!row.textContent.toLowerCase().includes(this.value.toLowerCase());if(!row.hidden)n++;}document.querySelector('#count').textContent=n+' files shown';});</script>'''
    (OUTPUT/'index.html').write_text(page('PHP archive browser',body),encoding='utf-8')
    (OUTPUT/'README.txt').write_text('Open index.html in a browser. All links work from disk.\nGenerated by scripts/export_temp_php.py using Pygments.\nOriginal PHP files are unchanged. No PHP code is executed.\nStatic previews omit PHP-generated content and disable scripts, forms, and network resources.\nKeep this inspection archive outside the live deployment (exclude TEMP/).\n',encoding='utf-8')
    print(f'Generated {len(files)} file views in {OUTPUT}')
if __name__=='__main__':
    generate()
